import sys,subprocess
from pathlib import Path
sys.path.insert(0,str(Path('backend').resolve()))
from app.local_codex import command,environment
prompt="""Use native built-in image_gen through ChatGPT login only, no paid API keys. Generate ONE high quality character illustration sheet, 4 columns x 2 rows of equal square panels, exact grid no gutters. Attached original Cyber Qiao is the identity reference: keep same recognizable purple short hair, transparent round glasses, big blue eyes, youthful friendly stylized illustrated face. Premium soft watercolor-digital character artwork with clear face and hands, warm ivory/pale lavender quiet backgrounds, minimal essential props, no text/numbers/logos. Each panel waist-up medium portrait centered with ample breathing room, consistent character scale. TOP ROW left to right: 1 longevity meal planning coach arranging a balanced vegetable grain protein plate with a weekly planner, 2 Chinese recipe coach cooking vegetables with wok and spatula, 3 dining-out coach seated reading a restaurant menu beside a simple place setting, 4 health review coach thoughtfully reviewing a clipboard with simple unlabeled graphs. BOTTOM ROW left to right: 5 nutrition supplement education coach explaining a vitamin capsule model beside fruit, no medicine dosing, 6 mindfulness coach seated comfortably eyes gently closed palms resting on knees with relaxed shoulders, 7 anti-aging exercise coach demonstrating a gentle resistance-band pull-apart at chest height, proper shoulders relaxed, 8 friendly neutral Qiao waving. No busy rooms, no decorative clutter, face and meaningful props readable on small mobile cards. Generate actual image with built-in image_gen and return path only; do not edit project files."""
Path('output/imagegen/qiao-coaches-prompt.txt').write_text(prompt,encoding='utf-8')
args=command()+['exec','--ephemeral','--skip-git-repo-check','--sandbox','read-only','-C',str(Path.cwd()),'-c','forced_login_method="chatgpt"','-c','approval_policy="never"','-i',str(Path('output/imagegen/qiao-original-reference.jpg').resolve()),'-']
r=subprocess.run(args,input=prompt.encode(),capture_output=True,env=environment('.runtime'),timeout=420)
Path('output/imagegen/qiao-coaches-result.txt').write_bytes(r.stdout+r.stderr)
print((r.stdout+r.stderr).decode('utf-8',errors='replace')[-2000:])
